declare const __brand: unique symbol;

type Brand<B> = { readonly [__brand]: B };

export type EmailAddress = string & Brand<'EmailAddress'>;
export type UserId = string & Brand<'UserId'>;

export function makeEmailAddress(email: string): EmailAddress {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    throw new TypeError(`Invalid email address: ${email}`);
  }
  return email as EmailAddress;
}

export function isEmailAddress(value: string): value is EmailAddress {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

export function makeUserId(id: string): UserId {
  if (!id || id.trim().length < 8) {
    throw new TypeError('UserId must be at least 8 non-empty characters');
  }
  return id.trim() as UserId;
}
